{
  "scenes": [
    {
      "scene_id": "scene_001",
      "narrative_beats": [
        {
          "beat_type": "Establishing / Status Quo",
          "description": "The cancelled last sailing and shuttered ticket window establish an atmosphere of suspension and closure. Lena is introduced as a clerk performing a careful, numbered ritual with envelope 17 and a brass key, suggesting procedural habit and hidden significance.",
          "approximate_location": "Opening",
          "confidence": 0.9
        },
        {
          "beat_type": "Inciting Complication",
          "description": "Tom delivers their father's medicine case with an urgent instruction — it must reach the clinic launch by six and must not be left in the locker — introducing a time-sensitive, high-stakes errand tied to a vulnerable family member.",
          "approximate_location": "Early",
          "confidence": 0.92
        },
        {
          "beat_type": "Mysterious Intrusion",
          "description": "An unseen Courier in an orange rain cape knocks and calls out the exact number 17 and locker location before retreating without answering Lena's question. The silhouette and unanswered identity create immediate suspense and imply a covert network.",
          "approximate_location": "Middle",
          "confidence": 0.95
        },
        {
          "beat_type": "Decision / Agency Beat",
          "description": "Lena stops Tom from reclaiming the medicine case and asserts she will personally deliver it to the launch, separating herself from Tom and taking sole responsibility for both the case and the mystery of the courier.",
          "approximate_location": "End",
          "confidence": 0.88
        }
      ],
      "tone_mood": "tense and secretive",
      "tone_shifts": [
        "Opens with quiet procedural calm (numbering envelopes, routine closing duties), then shifts sharply to unease and suspicion with the courier's knock and unanswered retreat"
      ],
      "location": null,
      "time_of_day": null,
      "int_ext": null,
      "characters_present": null
    },
    {
      "scene_id": "scene_002",
      "narrative_beats": [
        {
          "beat_type": "Discovery / Revelation",
          "description": "Lena opens the north locker and finds a cash box rather than anything related to the medicine errand, revealing that envelope 17 and the brass key were part of a separate, pre-arranged retrieval — the two errands are now entangled.",
          "approximate_location": "Opening",
          "confidence": 0.9
        },
        {
          "beat_type": "Ambiguous Encounter",
          "description": "The Old Man in an orange rain cape appears with a visible face, unlike the earlier silhouetted courier. His evasive answer about windows and fog refuses to confirm or deny his identity as the earlier courier, deepening the mystery of who is orchestrating events.",
          "approximate_location": "Middle",
          "confidence": 0.93
        },
        {
          "beat_type": "Clue / Object of Significance",
          "description": "The cash box contains a photograph of two children beside a ferry and a receipt noting storage paid through Friday. These objects suggest a personal or familial history connected to the ferry and a deadline, linking the covert errand to something intimate and time-bound.",
          "approximate_location": "Late Middle",
          "confidence": 0.88
        },
        {
          "beat_type": "Forward Momentum",
          "description": "Lena takes both the cash box and the medicine case toward the boathouse, consolidating the two objects and moving the action toward the next location and the six o'clock deadline.",
          "approximate_location": "End",
          "confidence": 0.85
        }
      ],
      "tone_mood": "eerie and quietly unsettling",
      "tone_shifts": [
        "The fog and invisible ferry horn create an otherworldly, disorienting atmosphere; the Old Man's cryptic deflection briefly heightens suspicion before Lena's methodical examination of the cash box returns the scene to a more investigative, controlled tone"
      ],
      "location": null,
      "time_of_day": null,
      "int_ext": null,
      "characters_present": null
    },
    {
      "scene_id": "scene_003",
      "narrative_beats": [
        {
          "beat_type": "Threshold / Safe Harbor",
          "description": "Lena arrives at the boathouse just before six, delivering the medicine case to Ruth, who refrigerates it. The ticking clock and the approaching deadline create compressed urgency even within this relatively sheltered interior space.",
          "approximate_location": "Opening",
          "confidence": 0.87
        },
        {
          "beat_type": "Character Detail / Humanizing Beat",
          "description": "Ruth notices Lena's bandage, now grey with grime, before anything else. This small observation grounds the scene in physical reality and hints at Lena's self-neglect or preoccupation — she has not tended to herself while managing others' needs.",
          "approximate_location": "Early",
          "confidence": 0.82
        },
        {
          "beat_type": "Offstage Complication",
          "description": "Tom calls to report an orange cape left on the bench outside the locked office. The cape connects to both the courier and the Old Man, suggesting one of them has been at the ticket office again, but Lena's instruction to leave it signals deliberate distance from the unknown party.",
          "approximate_location": "Middle",
          "confidence": 0.9
        },
        {
          "beat_type": "Suspended Expectation",
          "description": "The clock ticks toward six and no passenger arrives. The absence of the expected passenger is itself a beat — the launch errand is for Lena's father, but his non-appearance at the boathouse leaves his status and the errand's completion unresolved.",
          "approximate_location": "End",
          "confidence": 0.85
        }
      ],
      "tone_mood": "watchful and quietly anxious",
      "tone_shifts": [
        "The domestic warmth of Ruth's care (refrigerating the medicine, asking after the father) briefly softens the tension, but Tom's phone call about the orange cape reintroduces unease and suspicion at the scene's close"
      ],
      "location": null,
      "time_of_day": null,
      "int_ext": null,
      "characters_present": null
    },
    {
      "scene_id": "scene_004",
      "narrative_beats": [
        {
          "beat_type": "Reversal / Deliberate Undoing",
          "description": "Lena returns the cash box to the locker and locks it again with the brass key, reversing the retrieval she performed in scene 002. This circular action suggests the cash box was never meant to leave — or that Lena has decided to relinquish it — and closes the object's journey without explanation.",
          "approximate_location": "Opening",
          "confidence": 0.88
        },
        {
          "beat_type": "Transfer of Responsibility",
          "description": "Lena gives Tom the brass key, passing the means of access — and implicitly the burden of the mystery — to her brother. This handoff marks a shift in who holds agency over the locker and its contents.",
          "approximate_location": "Early Middle",
          "confidence": 0.85
        },
        {
          "beat_type": "Unresolved Personal Question",
          "description": "Tom asks whether the photograph showed their father. Lena's answer — that it had no date or names — neither confirms nor denies the connection, leaving the photograph's significance and the family's relationship to the ferry history open and unresolved.",
          "approximate_location": "Middle",
          "confidence": 0.9
        },
        {
          "beat_type": "Ambiguous Resolution / Open Ending",
          "description": "Ruth steers the clinic launch away with no one else visible aboard. The father is not seen returning. Ruth waves but the launch departs without delivering him. The scene ends with the siblings watching, the medicine presumably aboard but its recipient absent, and all central mysteries — the courier, the cash box, the photograph — unresolved.",
          "approximate_location": "End",
          "confidence": 0.92
        }
      ],
      "tone_mood": "melancholic and unresolved",
      "tone_shifts": [
        "The return of daylight (dawn) and Ruth's wave introduce a brief note of normalcy and farewell warmth, but the empty launch and unanswered questions about the photograph pull the scene back into quiet, lingering uncertainty"
      ],
      "location": null,
      "time_of_day": null,
      "int_ext": null,
      "characters_present": null
    }
  ]
}
